import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // best[t]: max covered sum of the prefix using at most t tiles
        long[] before2 = new long[4], before = new long[4];
        for (int i = 0; i < n; i++) {
            long[] current = before.clone(); // last element uncovered
            if (i > 0)
                for (int t = 1; t < 4; t++) current[t] = Math.max(before[t], before2[t - 1] + a[i - 1] + a[i]);
            before2 = before;
            before = current;
        }
        System.out.println(before[3]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// best[t]: max covered sum of the prefix using at most t tiles
	var before2, before [4]int64
	for i := 0; i < n; i++ {
		current := before // last element uncovered
		if i > 0 {
			for t := 1; t < 4; t++ {
				current[t] = max(before[t], before2[t-1]+a[i-1]+a[i])
			}
		}
		before2, before = before, current
	}
	fmt.Println(before[3])
}
